from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route("/ad")
def ad():
    mode = request.args["mode"]
    page = open("templates/ad.html").read()
    page = page.replace("workerId={{ workerid }}", "workerId={{ workerid }}&mode={{ mode }}")
    return render_template_string(page, mode=mode)

from typing import Annotated, Union

from flask import Flask
from flask_pydantic import validate
from pydantic import IPvAnyAddress, StringConstraints

app = Flask(__name__)
DomainName = Annotated[str, StringConstraints(pattern=r"^[a-z0-9.-]+$")]

@app.route("/config/<server_ip>")
@validate()
def show(server_ip: Union[IPvAnyAddress, DomainName]):
    path = f"/etc/app/{server_ip}.conf"
    with open(path) as fh:
        return fh.read()

